const $ = selector => document.querySelector(selector);
const state = { lang: localStorage.getItem('frontier-language') === 'en' ? 'en' : 'zh', apiBase: '', clientId: '', ready: false, session: sessionStorage.getItem('frontier-session') || '', email: sessionStorage.getItem('frontier-email') || '', isAdmin: false, data: null, inviteToken: new URL(location.href).searchParams.get('invite') || '' };
if (state.inviteToken) { const clean = new URL(location.href); clean.searchParams.delete('invite'); history.replaceState({}, '', clean); }
const esc = value => String(value ?? '').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
const message = (zh, en) => state.lang === 'zh' ? zh : en;
async function api(path, options = {}) { const response = await fetch(state.apiBase + path, { ...options, headers: { 'Content-Type': 'application/json', ...(state.session ? { Authorization: `Bearer ${state.session}` } : {}), ...(options.headers || {}) } }); const data = await response.json().catch(() => ({})); if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`); return data; }
function date(value) { return value ? new Date(value).toLocaleString(state.lang === 'zh' ? 'zh-CN' : 'en-US', { year: 'numeric', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '—'; }
function renderData() {
  if (!state.data) return;
  const { users = [], invitations = [] } = state.data;
  const active = users.filter(row => !row.revokedAt).length, pending = invitations.filter(row => !row.acceptedAt && !row.revokedAt && Date.parse(row.expiresAt) > Date.now()).length;
  $('#admin-summary').textContent = message(`${users.length} 个账号 · ${active} 个可访问 · ${pending} 个待接受邀请`, `${users.length} accounts · ${active} active · ${pending} pending invitations`);
  $('#admin-users').innerHTML = users.length ? users.map(row => `<div class="admin-row"><div><b>${esc(row.email)}</b><small>${row.revokedAt ? message('已撤销', 'Revoked') : message('可访问', 'Active')} · ${message('注册', 'Joined')} ${esc(date(row.createdAt))} · ${message('最近登录', 'Last sign-in')} ${esc(date(row.lastSignedInAt))}</small></div>${row.email.toLowerCase() === state.email.toLowerCase() ? '' : `<button type="button" class="${row.revokedAt ? '' : 'danger'}" data-user-id="${esc(row.id)}" data-action="${row.revokedAt ? 'restore' : 'revoke'}">${row.revokedAt ? message('恢复访问', 'Restore access') : message('撤销访问', 'Revoke access')}</button>`}</div>`).join('') : `<p class="muted">${message('暂无账号', 'No accounts yet')}</p>`;
  $('#admin-invitations').innerHTML = invitations.length ? invitations.map(row => { const pending = !row.acceptedAt && !row.revokedAt && Date.parse(row.expiresAt) > Date.now(); const status = row.acceptedAt ? message('已接受', 'Accepted') : row.revokedAt ? message('已撤销', 'Revoked') : pending ? message('待接受', 'Pending') : message('已过期', 'Expired'); return `<div class="admin-row"><div><b>${esc(row.email)}</b><small>${status} · ${message('创建', 'Created')} ${esc(date(row.createdAt))} · ${message('到期', 'Expires')} ${esc(date(row.expiresAt))}</small></div>${pending ? `<button type="button" class="danger" data-invite-id="${esc(row.id)}">${message('取消邀请', 'Cancel invitation')}</button>` : ''}</div>`; }).join('') : `<p class="muted">${message('暂无邀请', 'No invitations yet')}</p>`;
}
async function loadAdmin() { if (!state.isAdmin) return; state.data = await api('/admin/overview'); renderData(); }
function renderStatus() {
  $('#admin-content').hidden = !state.isAdmin;
  $('#admin-gate').hidden = state.isAdmin;
  $('#admin-gate').textContent = !state.ready ? message('管理功能等待 Google 登录与账号服务配置。', 'Admin access is waiting for Google sign-in and account service setup.') : !state.session ? state.inviteToken ? message('请使用收到邀请的 Google 邮箱登录，接受邀请。', 'Sign in with the invited Google account to accept access.') : message('请用 Google 账号登录。', 'Sign in with Google.') : message('此账号没有管理员权限。', 'This account does not have admin access.');
  $('#google-signin').hidden = !state.ready || !!state.session;
  $('#admin-session').hidden = !state.session;
  $('#user-email').textContent = state.email;
}
function setLanguage(lang) { state.lang = lang; localStorage.setItem('frontier-language', lang); document.documentElement.lang = lang === 'zh' ? 'zh-CN' : 'en'; document.querySelectorAll('[data-zh]').forEach(el => el.textContent = el.dataset[lang]); $('#lang').textContent = lang === 'zh' ? 'English' : '中文'; renderStatus(); renderData(); }
function clearSession() { state.session = ''; state.email = ''; state.isAdmin = false; state.data = null; sessionStorage.removeItem('frontier-session'); sessionStorage.removeItem('frontier-email'); renderStatus(); }
async function signIn(response) {
  try { const result = await api('/auth/google', { method: 'POST', body: JSON.stringify({ credential: response.credential, inviteToken: state.inviteToken || undefined }) }); state.inviteToken = ''; state.session = result.session; state.email = result.email; state.isAdmin = result.isAdmin; sessionStorage.setItem('frontier-session', result.session); sessionStorage.setItem('frontier-email', result.email); $('#login-message').textContent = state.isAdmin ? '' : message('邀请已接受。你现在可使用公开航班雷达并下载日历提醒。', 'Invitation accepted. You can use the flight radar and download calendar reminders.'); await loadAdmin(); renderStatus(); } catch (error) { $('#login-message').textContent = error.message; }
}
function loadGoogleButton() { const script = document.createElement('script'); script.src = 'https://accounts.google.com/gsi/client'; script.async = true; script.onload = () => { google.accounts.id.initialize({ client_id: state.clientId, callback: signIn }); google.accounts.id.renderButton($('#google-button'), { theme: 'outline', size: 'large', text: 'signin_with', width: 260 }); }; script.onerror = () => { $('#login-message').textContent = message('无法载入 Google 登录。', 'Could not load Google sign-in.'); }; document.head.append(script); }
async function init() { try { const config = await fetch('config.json').then(r => r.json()); state.apiBase = (config.apiBase || '').replace(/\/$/, ''); state.clientId = config.googleClientId || ''; if (state.apiBase && state.clientId) { await api('/health'); state.ready = true; loadGoogleButton(); } if (state.ready && state.session) { const me = await api('/me'); state.email = me.email; state.isAdmin = me.isAdmin; await loadAdmin(); } } catch (error) { if (error.message.includes('401') || error.message.includes('403')) clearSession(); else $('#login-message').textContent = error.message; } setLanguage(state.lang); }
$('#lang').addEventListener('click', () => setLanguage(state.lang === 'zh' ? 'en' : 'zh'));
$('#sign-out').addEventListener('click', clearSession);
$('#admin-invite-form').addEventListener('submit', async event => { event.preventDefault(); try { const email = $('#admin-invite-email').value.trim(); const result = await api('/admin/invitations', { method: 'POST', body: JSON.stringify({ email }) }); $('#admin-invite-email').value = ''; $('#invite-link').value = result.link; $('#invite-result').hidden = false; $('#admin-message').textContent = message(`已为 ${email} 创建一次性邀请链接，请复制并自行发给对方。`, `One-time invitation link created for ${email}. Copy and share it yourself.`); await loadAdmin(); } catch (error) { $('#admin-message').textContent = error.message; } });
$('#copy-invite').addEventListener('click', async () => { try { await navigator.clipboard.writeText($('#invite-link').value); $('#admin-message').textContent = message('邀请链接已复制。', 'Invitation link copied.'); } catch { $('#invite-link').select(); $('#admin-message').textContent = message('请手动复制选中的链接。', 'Please copy the selected link.'); } });
$('#admin-users').addEventListener('click', async event => { const button = event.target.closest('button[data-user-id]'); if (!button) return; const action = button.dataset.action; if (action === 'revoke' && !confirm(message('撤销此账号访问？', 'Revoke this account’s access?'))) return; try { await api(`/admin/users/${encodeURIComponent(button.dataset.userId)}/${action}`, { method: 'POST' }); await loadAdmin(); } catch (error) { $('#admin-message').textContent = error.message; } });
$('#admin-invitations').addEventListener('click', async event => { const button = event.target.closest('button[data-invite-id]'); if (!button) return; try { await api(`/admin/invitations/${encodeURIComponent(button.dataset.inviteId)}/revoke`, { method: 'POST' }); await loadAdmin(); } catch (error) { $('#admin-message').textContent = error.message; } });
init();
